// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        // receiver must be a plain EOA so the transfer cannot revert for extrinsic reasons
        vm.assume(receiver.code.length == 0);
        // fund c so the reference transfer always succeeds (avoid balance-driven reverts)
        vm.deal(address(c), amount);
        // owner is address(this) (deployer in setUp); call as owner so the require passes
        vm.prank(address(this));
        uint256 before = receiver.balance;
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 delta = receiver.balance - before;
        assertTrue(!ok || delta == amount);
    }
}
